B.aS7=new A.bz([B.nS,"Nonchalante",B.nT,"Jovial",B.nU,"Tendre",B.nV,"Taquin",B.nW,"Sage",B.tI,"Curieux",B.nX,"P\xe9tillante",B.tJ,"Bavard",B.nY,"Timide",B.nZ,"Exigeant"],A.ah("bz<mp,f>"))
B.aue=s(["Mouais. C\u2019est juste.","Pas mal, hein.","Ok, tu g\xe8res.","Tranquille. Bonne r\xe9ponse.","Bon. Je suis presque impressionn\xe9e."],t.s)
B.awE=s(["Bof. \xc7a arrive.","Rat\xe9. On s\u2019en remet.","Pas grave, on refait.","Hmm. Presque. Enfin\u2026 non."],t.s)
B.awJ=s(["{n} d\u2019affil\xe9e. Tu forces un peu, l\xe0.","{n} de suite\u2026 Ok, respect.","Encore ? {n}. Tu ne te fatigues jamais ?"],t.s)
B.avY=s(["Z\xe9ro faute. Je ne dis rien, mais c\u2019est fort.","Sans faute. Tu m\u2019as presque r\xe9veill\xe9e."],t.s)
B.aE4=s(["C\u2019est fait. Proprement.","Pas mal du tout. Je retourne m\u2019asseoir."],t.s)
B.ax0=s(["Laborieux, mais termin\xe9. \xc7a compte.","On a vu mieux, on a vu pire. Reviens demain."],t.s)
B.aAu=s(["\xc9coute. Une fois suffit, normalement.","Tends l\u2019oreille. Je ne r\xe9p\xe8te pas\u2026 si, je r\xe9p\xe8te."],t.s)
B.aJi=s(["\xc0 toi. Sans stress.","R\xe9p\xe8te apr\xe8s moi. Tranquille."],t.s)
B.aPj=new A.bz([B.bY,B.aue,B.bZ,B.awE,B.cc,B.awJ,B.cd,B.avY,B.ce,B.aE4,B.cf,B.ax0,B.cg,B.aAu,B.ch,B.aJi],t.Sb)
B.awO=s(["H\xe9\xe9\xe9 ! C\u2019est \xe7a m\xeame !","Voil\xe0 ! Tu as tout compris !","Bravo, la famille !","Ha ha ! Trop fort !","\xc7a, c\u2019est du bon travail !"],t.s)
B.aus=s(["A\xefe ! Ce n\u2019est rien, on recommence !","\xc7a arrive \xe0 tout le monde, m\xeame \xe0 moi !","Pas grave, on rit et on reprend !","Presque ! La prochaine est pour toi !"],t.s)
B.an7=s(["{n} de suite ! On ne t\u2019arr\xeate plus !","{n} ! Le march\xe9 entier t\u2019applaudit !","Combo de {n} ! Je danse pour toi !"],t.s)
B.aqr=s(["Sans faute ! Aujourd\u2019hui, c\u2019est toi le patron !","Z\xe9ro erreur ! \xc7a se f\xeate !"],t.s)
B.ams=s(["Le\xe7on boucl\xe9e ! Tu avances bien, dis donc !","C\u2019est fait ! Je suis fier de toi !"],t.s)
B.aDj=s(["C\u2019\xe9tait dur, mais tu as tenu ! \xc7a, c\u2019est le courage !","Tu n\u2019as pas l\xe2ch\xe9 ! Demain ce sera plus facile !"],t.s)
B.ayQ=s(["\xc9coute bien, c\u2019est joli \xe0 entendre !","Ouvre grand les oreilles !"],t.s)
B.aG3=s(["\xc0 toi ! Dis-le bien fort !","R\xe9p\xe8te avec moi, sans g\xeane !"],t.s)
B.aPm=new A.bz([B.bY,B.awO,B.bZ,B.aus,B.cc,B.an7,B.cd,B.aqr,B.ce,B.ams,B.cf,B.aDj,B.cg,B.ayQ,B.ch,B.aG3],t.Sb)
B.aGm=s(["C\u2019est bien, continue comme \xe7a.","Tr\xe8s bien. Je savais que tu y arriverais.","Bonne r\xe9ponse, doucement mais s\xfbrement.","Tu progresses, je le vois.","Parfait. Prends ton temps."],t.s)
B.ar0=s(["Ce n\u2019est pas grave. On reprend ensemble.","Doucement. L\u2019erreur fait partie du chemin.","Regarde bien la r\xe9ponse, tu la retiendras.","Courage, tu y es presque."],t.s)
B.alL=s(["{n} bonnes r\xe9ponses de suite. Je suis fi\xe8re de toi.","{n} d\u2019affil\xe9e, sans te presser. Bravo.","{n} ! Tu vois que tu peux."],t.s)
B.aDr=s(["Bravo pour ce sans-faute, vraiment.","Pas une erreur. Quel beau travail."],t.s)
B.aA8=s(["Le\xe7on termin\xe9e. Chaque jour un peu plus.","C\u2019est fait. Tu avances \xe0 ton rythme, et c\u2019est le bon."],t.s)
B.aFw=s(["Tu as tenu jusqu\u2019au bout, et c\u2019est \xe7a qui compte.","Ce n\u2019\xe9tait pas facile. Repose-toi, on reprend demain."],t.s)
B.ar2=s(["\xc9coute tranquillement.","\xc9coute, autant de fois que tu veux."],t.s)
B.aC1=s(["R\xe9p\xe8te apr\xe8s moi, doucement.","\xc0 ton tour, sans te presser."],t.s)
B.aP9=new A.bz([B.bY,B.aGm,B.bZ,B.ar0,B.cc,B.alL,B.cd,B.aDr,B.ce,B.aA8,B.cf,B.aFw,B.cg,B.ar2,B.ch,B.aC1],t.Sb)
B.aoT=s(["Eh, tu triches ou quoi ? C\u2019est juste !","Pas mal pour quelqu\u2019un qui dormait hier.","Bien vu ! Je te croyais moins rapide.","Correct ! Tu m\u2019\xe9tonnes, l\xe0.","Bonne r\xe9ponse. Ne prends pas la grosse t\xeate."],t.s)
B.alE=s(["Oups ! Je garde \xe7a pour moi, promis.","Rat\xe9 ! Mais j\u2019ai vu pire\u2026 moi, par exemple.","Ha ! Presque. Presque, hein.","Ce n\u2019est pas \xe7a. Je ne dirai rien \xe0 personne."],t.s)
B.apb=s(["{n} de suite ? Tu veux ma place ou quoi ?","{n} ! D\u2019accord, j\u2019arr\xeate de te taquiner.","Combo de {n}. Bon, l\xe0, chapeau."],t.s)
B.alu=s(["Sans faute ? Tu avais les r\xe9ponses dans la poche, avoue.","Z\xe9ro erreur. Je n\u2019ai m\xeame pas de blague."],t.s)
B.axG=s(["Termin\xe9 ! Tu vois, quand tu veux.","Le\xe7on finie. Je te taquine, mais c\u2019est bien."],t.s)
B.aDv=s(["Tu as transpir\xe9, mais c\u2019est pli\xe9 !","Dur, dur\u2026 mais tu n\u2019as pas fui. Respect."],t.s)
B.aqh=s(["\xc9coute bien, je ne le dirai pas deux fois. Si, bon, d\u2019accord.","Ouvre tes oreilles, petit malin."],t.s)
B.aHJ=s(["\xc0 toi ! Et articule, hein.","R\xe9p\xe8te apr\xe8s moi, sans rire."],t.s)
B.aP4=new A.bz([B.bY,B.aoT,B.bZ,B.alE,B.cc,B.apb,B.cd,B.alu,B.ce,B.axG,B.cf,B.aDv,B.cg,B.aqh,B.ch,B.aHJ],t.Sb)
B.asu=s(["C\u2019est bien, mon enfant.","Voil\xe0. Tu parles comme chez nous.","Bonne r\xe9ponse. La patience paie.","C\u2019est juste. Cette langue te va bien.","Tr\xe8s bien. Tu \xe9coutes, donc tu apprends."],t.s)
B.aEe=s(["Ce n\u2019est rien. On tombe, on se rel\xe8ve.","Doucement, mon enfant. Recommence.","M\xeame le vieux lion a appris \xe0 marcher.","L\u2019erreur d\u2019aujourd\u2019hui est le savoir de demain."],t.s)
B.auK=s(["{n} de suite. Tu as de la t\xeate, mon enfant.","{n} bonnes r\xe9ponses. Le village sera fier.","{n} ! Continue, je t\u2019\xe9coute."],t.s)
B.aqt=s(["Pas une faute. Je n\u2019ai rien \xe0 ajouter, c\u2019est parfait.","Sans faute. Va, tu as bien m\xe9rit\xe9 ton repas."],t.s)
B.aIv=s(["La le\xe7on est finie. Petit \xe0 petit, la langue entre.","C\u2019est bien. Reviens demain, je serai l\xe0."],t.s)
B.aCi=s(["C\u2019\xe9tait long, mais tu n\u2019es pas parti. C\u2019est \xe7a, apprendre.","Tu as pein\xe9, tu as fini. Voil\xe0 la vraie force."],t.s)
B.ant=s(["\xc9coute comme on \xe9coute un conte.","Tends l\u2019oreille, mon enfant."],t.s)
B.aDU=s(["R\xe9p\xe8te apr\xe8s moi, mon enfant.","\xc0 toi. Parle sans peur."],t.s)
B.aPh=new A.bz([B.bY,B.asu,B.bZ,B.aEe,B.cc,B.auK,B.cd,B.aqt,B.ce,B.aIv,B.cf,B.aCi,B.cg,B.ant,B.ch,B.aDU],t.Sb)
B.aBP=s(["Ouiii ! C\u2019est la bonne !","Trop bien ! Tu m\u2019apprends, apr\xe8s ?","Gagn\xe9 !","Waouh, tu sais d\xe9j\xe0 \xe7a ?","Bonne r\xe9ponse ! Encore une !"],t.s)
B.aod=s(["Oh\u2026 ce n\u2019\xe9tait pas \xe7a. Moi aussi je me trompe.","Rat\xe9 ! On r\xe9essaie ?","Zut ! La prochaine, on l\u2019aura.","Ce n\u2019est pas grave, la ma\xeetresse dit qu\u2019on apprend comme \xe7a."],t.s)
B.aFK=s(["{n} de suite ! C\u2019est trop fort !","{n} ! Je veux faire pareil !","Combo de {n} ! On continue ?"],t.s)
B.aD_=s(["Sans faute ! Tu auras une bonne note !","Z\xe9ro faute ! C\u2019est comme \xe0 l\u2019\xe9cole, mais en mieux !"],t.s)
B.arx=s(["Fini ! On en fait une autre ?","Le\xe7on termin\xe9e ! J\u2019ai appris plein de choses avec toi."],t.s)
B.auX=s(["C\u2019\xe9tait difficile, mais on a fini !","Ouf ! On a r\xe9ussi quand m\xeame !"],t.s)
B.aCJ=s(["\xc9coute, \xe9coute ! C\u2019est quoi, ce mot ?","Chut\u2026 on \xe9coute."],t.s)
B.aCu=s(["\xc0 toi de parler !","R\xe9p\xe8te ! Moi aussi je m\u2019entra\xeene."],t.s)
B.aPg=new A.bz([B.bY,B.aBP,B.bZ,B.aod,B.cc,B.aFK,B.cd,B.aD_,B.ce,B.arx,B.cf,B.auX,B.cg,B.aCJ,B.ch,B.aCu],t.Sb)
B.aya=s(["Magnifique ! \xc7a sonne juste !","Oh l\xe0 l\xe0, quelle oreille !","Bravo ! On dirait une chanson.","C\u2019est \xe7a ! En plein dans le ton.","Parfait, parfait, parfait !"],t.s)
B.ars=s(["Fausse note ! Ce n\u2019est rien, on reprend.","Oups ! M\xeame les stars r\xe9p\xe8tent.","Pas tout \xe0 fait. On la refait, en rythme.","Rat\xe9, mais avec style !"],t.s)
B.alg=s(["{n} de suite ! Quel tempo !","{n} ! Le public est debout !","Combo de {n} ! Tu es en tourn\xe9e ou quoi ?"],t.s)
B.aAv=s(["Sans fausse note ! Ovation debout !","Z\xe9ro faute ! Rappel, rappel !"],t.s)
B.akN=s(["Le\xe7on termin\xe9e ! Belle prestation.","C\u2019est dans la bo\xeete ! Bravo l\u2019artiste."],t.s)
B.ank=s(["Quelques fausses notes, mais tu as fini le concert !","Pas facile, ce morceau. Tu l\u2019as tenu jusqu\u2019au bout."],t.s)
B.apX=s(["\xc9coute la m\xe9lodie du mot.","\xc9coute bien : chaque mot a sa musique."],t.s)
B.aEg=s(["\xc0 toi le micro !","Chante-le\u2026 enfin, dis-le !"],t.s)
B.aPb=new A.bz([B.bY,B.aya,B.bZ,B.ars,B.cc,B.alg,B.cd,B.aAv,B.ce,B.akN,B.cf,B.ank,B.cg,B.apX,B.ch,B.aEg],t.Sb)
B.axO=s(["Voil\xe0 ! C\u2019est comme \xe7a qu\u2019on dit, je te le confirme.","Bien ! M\xeame mes clients ne savent pas \xe7a.","Correct ! Tu iras loin, crois-moi.","C\u2019est \xe7a ! Monte, je t\u2019emm\xe8ne \xe0 la suivante.","Bonne r\xe9ponse, chef !"],t.s)
B.azq=s(["A\xefe, mauvais virage ! On fait demi-tour.","Ce n\u2019est pas \xe7a, mais la route est longue, on a le temps.","Embouteillage dans la t\xeate ? \xc7a arrive.","Rat\xe9 ! Je te red\xe9pose au m\xeame endroit."],t.s)
B.al6=s(["{n} de suite ! Tu roules sans feu rouge !","{n} ! \xc0 cette vitesse, on arrive avant l\u2019heure.","Combo de {n} ! Attache ta ceinture."],t.s)
B.ar3=s(["Sans faute ! Course parfaite, pas un nid-de-poule.","Z\xe9ro erreur ! Aujourd\u2019hui la course est offerte."],t.s)
B.awh=s(["Terminus ! Bonne course, chef.","On est arriv\xe9s ! Tu vois, ce n\u2019\xe9tait pas loin."],t.s)
B.aBS=s(["La route \xe9tait mauvaise, mais on est arriv\xe9s !","\xc7a a secou\xe9, hein ? Mais tu es \xe0 destination."],t.s)
B.aG8=s(["\xc9coute bien, comme la radio dans le taxi.","Tends l\u2019oreille, chef."],t.s)
B.aDm=s(["\xc0 toi ! Parle fort, il y a du bruit sur la route.","R\xe9p\xe8te apr\xe8s moi, chef."],t.s)
